package com.walletrescue;
import android.os.Bundle;import android.os.SystemClock;import android.content.ClipData;import android.content.ClipboardManager;import android.content.Context;import android.widget.Button;import android.widget.EditText;import android.widget.ScrollView;import android.widget.TextView;import android.widget.Toast;import androidx.appcompat.app.AppCompatActivity;import java.util.ArrayList;import java.util.List;import java.util.Locale;
public class MainActivity extends AppCompatActivity{
 private EditText inputText;private TextView outputText,statusText,speedText,walletText;private Button startBtn,stopBtn,create12Btn,create24Btn,copyBtn;private ScrollView outputScroll;private volatile boolean scanCancelled=false,scanning=false;private long t0;private WalletCore.WalletResult currentWallet;
 @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);inputText=findViewById(R.id.inputText);outputText=findViewById(R.id.outputText);statusText=findViewById(R.id.statusText);speedText=findViewById(R.id.speedText);walletText=findViewById(R.id.walletText);startBtn=findViewById(R.id.startBtn);stopBtn=findViewById(R.id.stopBtn);outputScroll=findViewById(R.id.outputScroll);create12Btn=findViewById(R.id.create12Btn);create24Btn=findViewById(R.id.create24Btn);copyBtn=findViewById(R.id.copyBtn);stopBtn.setEnabled(false);copyBtn.setEnabled(false);startBtn.setOnClickListener(v->startScan());stopBtn.setOnClickListener(v->stopScan());create12Btn.setOnClickListener(v->createWallet(12));create24Btn.setOnClickListener(v->createWallet(24));copyBtn.setOnClickListener(v->copyMnemonic());}
 private void createWallet(int count){create12Btn.setEnabled(false);create24Btn.setEnabled(false);statusText.setText("در حال تولید کیف پول آفلاین روی دستگاه…");new Thread(()->{try{WalletCore.WalletResult w=WalletCore.create(count);currentWallet=w;String report="کیف پول جدید ساخته شد — "+count+" کلمه\n\nعبارت بازیابی (آن را با هیچ‌کس به اشتراک نگذارید):\n"+w.mnemonic()+"\n\nBitcoin BTC\nآدرس: "+w.btc+"\nمسیر: "+w.btcPath+"\n\nEthereum ETH\nآدرس: "+w.eth+"\nمسیر: "+w.ethPath+"\n\nTRON / TRC20\nآدرس: "+w.tron+"\nمسیر: "+w.tronPath+"\n\nموجودی‌ها هنوز بررسی نشده‌اند. برای بررسی BTC، آدرس را در بخش پایین وارد کنید.\n\nهشدار: در این نسخه پشتیبان رمزگذاری‌شده هنوز پیاده‌سازی نشده است.";runOnUiThread(()->{walletText.setText(report);statusText.setText("کیف پول به‌صورت آفلاین ساخته شد.");copyBtn.setEnabled(true);});}catch(Exception e){runOnUiThread(()->statusText.setText("خطا در تولید کیف پول: "+(e.getMessage()==null?e.toString():e.getMessage())));}finally{runOnUiThread(()->{create12Btn.setEnabled(true);create24Btn.setEnabled(true);});}}).start();}
 private void copyMnemonic(){if(currentWallet==null)return;ClipboardManager cm=(ClipboardManager)getSystemService(Context.CLIPBOARD_SERVICE);cm.setPrimaryClip(ClipData.newPlainText("BIP39 recovery phrase",currentWallet.mnemonic()));Toast.makeText(this,"عبارت بازیابی کپی شد؛ کلیپ‌بورد را امن نگه‌دار و پاک کن.",Toast.LENGTH_LONG).show();}
 private void startScan(){if(scanning)return;List<String> list=new ArrayList<>();for(String s:inputText.getText().toString().split("[\\r\\n,;\\s]+"))if(!s.trim().isEmpty())list.add(s.trim());if(list.isEmpty()){statusText.setText("آدرس عمومی BTC را وارد کنید.");return;}if(list.size()>100){statusText.setText("حداکثر ۱۰۰ آدرس مجاز است.");return;}scanCancelled=false;scanning=true;startBtn.setEnabled(false);stopBtn.setEnabled(true);outputText.setText("بررسی آدرس‌های عمومی BTC آغاز شد…");statusText.setText("در حال بررسی BTC…");speedText.setText("۰ از "+fmt(list.size()));t0=SystemClock.elapsedRealtime();new Thread(()->{try{String report=AddressScanner.scan(this,list,0,(done,total)->runOnUiThread(()->{if(!scanCancelled){long ms=Math.max(1,SystemClock.elapsedRealtime()-t0);statusText.setText("BTC — "+done+" از "+total);speedText.setText(fmt(done)+" / "+fmt(total)+" آدرس | "+fmt(done*1000L/ms)+" آدرس/ثانیه");}}),()->scanCancelled);runOnUiThread(()->{outputText.setText(report);statusText.setText(scanCancelled?"بررسی متوقف شد.":"بررسی BTC تمام شد.");speedText.setText(" ");finishScan();});}catch(Exception e){runOnUiThread(()->{statusText.setText(scanCancelled?"بررسی متوقف شد.":"خطا در بررسی BTC");outputText.append("\n"+(e.getMessage()==null?e.toString():e.getMessage()));speedText.setText(" ");finishScan();});}}).start();}
 private void stopScan(){scanCancelled=true;statusText.setText("درخواست توقف بررسی ارسال شد…");}private void finishScan(){scanning=false;startBtn.setEnabled(true);stopBtn.setEnabled(false);}private static String fmt(long n){return String.format(Locale.US,"%,d",n);}
}